import { atom, read, update } from 'claude-code'
import type { EngineInterface, PluginOptions, Register, TurnStepResult } from 'claude-code'

import type { QueuedPart, RouterSettings, RouterStats, Tier, TurnRoute } from '../types'
import { maxTier, plan, rank } from './classify'
import type { PartPlan, Plan } from './classify'
import { chooseSwitch, costOf, family, formatUsd, promptTokens } from './cost'

const NAME = 'model-router'

const EMPTY_STATS: RouterStats = { prompts: 0, splits: 0, steps: 0, cost: 0, baseline: 0, byModel: {} }

const settings = atom({ plugin: 'model-router', key: 'settings' } as const, {
  isEnabled: true,
  split: 'sequential',
})
const turns = atom({ plugin: 'model-router', key: 'turns' } as const, {})
const pending = atom({ plugin: 'model-router', key: 'pending' } as const, null)
const queue = atom({ plugin: 'model-router', key: 'queue' } as const, [])
const cache = atom({ plugin: 'model-router', key: 'cache' } as const, { contextTokens: 0 })
const lastTier = atom({ plugin: 'model-router', key: 'lastTier' } as const, null)
const stats = atom({ plugin: 'model-router', key: 'stats' } as const, EMPTY_STATS)

const EFFORT: Record<Tier, 'low' | 'medium' | 'high'> = {
  fast: 'low',
  balanced: 'medium',
  deep: 'high',
  max: 'high',
}

// A rough per-request output size, for the cache-aware switch estimate
const EXPECTED_OUTPUT: Record<Tier, number> = { fast: 400, balanced: 1500, deep: 3000, max: 4000 }

const EDITING_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

const CLASSIFIER_LABELS: Record<'fast' | 'balanced' | 'deep', string> = {
  fast: 'simple: a question, explanation, lookup or small talk a small fast model answers well',
  balanced: 'moderate: a focused code change, bug fix or small feature in a few files',
  deep: 'complex: a large build, multi-file feature, hard debugging, or architecture and design work',
}

type Config = {
  models: Record<Tier, string>
  classifier: 'hybrid' | 'heuristic'
  split: RouterSettings['split']
  setEffort: boolean
  escalate: boolean
  cacheAware: boolean
}

function configOf(options: PluginOptions): Config {
  const str = (key: string, fallback: string) => {
    const v = options[key]
    return typeof v === 'string' && v.trim() ? v.trim() : fallback
  }
  const bool = (key: string, fallback: boolean) => {
    const v = options[key]
    return typeof v === 'boolean' ? v : fallback
  }
  return {
    models: {
      fast: str('fastModel', 'claude-haiku-5-5'),
      balanced: str('balancedModel', 'claude-sonnet-5-5'),
      deep: str('deepModel', 'claude-opus-5-5'),
      max: str('maxModel', 'claude-fable-5-1'),
    },
    classifier: str('classifier', 'hybrid') === 'heuristic' ? 'heuristic' : 'hybrid',
    split: str('split', 'sequential') === 'off' ? 'off' : 'sequential',
    setEffort: bool('setEffort', true),
    escalate: bool('escalate', true),
    cacheAware: bool('cacheAware', true),
  }
}

function label(model: string): string {
  const f = family(model)
  return f.charAt(0).toUpperCase() + f.slice(1)
}

function routeOf(part: PartPlan | QueuedPart, index?: number, total?: number): TurnRoute {
  return {
    tier: part.tier,
    category: part.category,
    reasons: part.reasons,
    ...(index !== undefined && total !== undefined && total > 1 ? { part: { index, total } } : {}),
  }
}

function clip(text: string, max = 160): string {
  const one = text.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

function nextTier(tier: Tier): Tier {
  return tier === 'fast' ? 'balanced' : 'deep'
}

// Why a turn should move up a tier after this step, if it should.
function escalation(route: TurnRoute, index: number, result: TurnStepResult): string | undefined {
  if (rank(route.tier) >= rank('deep')) return undefined
  if (result.stopReason === 'max_tokens') return 'ran out of output tokens'
  if (route.tier === 'fast' && result.toolUses.some(use => EDITING_TOOLS.has(use.name))) {
    return 'started editing files'
  }
  if (route.tier === 'fast' && index >= 5) return 'took more than 5 steps'
  if (route.tier === 'balanced' && index >= 14) return 'took more than 14 steps'
  return undefined
}

// Asks the small model about the parts the rules were unsure of.
async function refine($: EngineInterface, p: Plan, model: string): Promise<Plan> {
  const parts = await Promise.all(
    p.parts.map(async part => {
      if (part.confidence >= 0.34 || part.category === 'follow-up') return part
      const labels = Object.values(CLASSIFIER_LABELS)
      const answer = await $.model
        .classify(`Classify how hard this coding-assistant request is:\n\n${part.text.slice(0, 4000)}`, labels, {
          model,
        })
        .catch(() => undefined)
      const tier = (Object.keys(CLASSIFIER_LABELS) as Array<keyof typeof CLASSIFIER_LABELS>).find(
        t => CLASSIFIER_LABELS[t] === answer,
      )
      if (!tier) return part
      return { ...part, tier, confidence: 1, reasons: [...part.reasons, `Haiku classifier said ${tier}`] }
    }),
  )
  const tier = parts.reduce<Tier>((t, part) => maxTier(t, part.tier), 'fast')
  return { ...p, parts, tier }
}

async function addStats($: EngineInterface, change: (s: RouterStats) => RouterStats): Promise<void> {
  await update($, stats, change)
  const lifetime = ((await $.store.get('lifetime')) as RouterStats | undefined) ?? EMPTY_STATS
  await $.store.set('lifetime', change(lifetime))
}

function describeStats(s: RouterStats): string[] {
  const saved = s.baseline - s.cost
  const lines = [
    `${s.prompts} prompts routed, ${s.splits} split, ${s.steps} model requests`,
    `cost ≈ ${formatUsd(s.cost)} vs ≈ ${formatUsd(s.baseline)} on the session model: saved ≈ ${formatUsd(saved)}${
      s.baseline > 0 ? ` (${Math.round((saved / s.baseline) * 100)}%)` : ''
    }`,
  ]
  for (const [model, tally] of Object.entries(s.byModel)) {
    lines.push(`  ${model}: ${tally.steps} requests, ≈ ${formatUsd(tally.cost)}`)
  }
  return lines
}

function describePlan(p: Plan, config: Config): string[] {
  const lines: string[] = []
  if (p.parts.length > 1) lines.push(`Split into ${p.parts.length} turns:`)
  p.parts.forEach((part, i) => {
    const model = config.models[part.tier]
    const head = p.parts.length > 1 ? `${i + 1}. ` : ''
    lines.push(`${head}${label(model)} (${model}, ${part.tier}) · ${part.category} · score ${part.score}`)
    lines.push(`   ${part.reasons.join('; ')}`)
    if (p.parts.length > 1) lines.push(`   "${clip(part.text, 100)}"`)
  })
  return lines
}

export const register: Register = (on, options) => {
  const config = configOf(options)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'router',
      description: 'Model router: status, on, off, split on|off, explain <prompt>, reset',
      argumentHint: '[status|on|off|split on|off|explain <prompt>|reset]',
    })
    const saved = (await $.store.get('settings')) as RouterSettings | undefined
    await update($, settings, () => saved ?? { isEnabled: true, split: config.split })
    $.ui.status(saved?.isEnabled === false ? '⇄ router off' : '⇄ router on')

    return next(e)
  })

  on('command.run', { command: 'router' }, async ($, e) => {
    const [verb = 'status', ...rest] = e.args.trim().split(/\s+/).filter(Boolean)
    const current = await read($, settings)
    const save = async (s: RouterSettings) => {
      await update($, settings, () => s)
      await $.store.set('settings', s)
      $.ui.status(s.isEnabled ? '⇄ router on' : '⇄ router off')
    }

    switch (verb.toLowerCase()) {
      case 'on':
        await save({ ...current, isEnabled: true })
        return { text: 'Model router on: prompts are routed by complexity.' }
      case 'off':
        await save({ ...current, isEnabled: false })
        await update($, queue, () => [])
        return { text: 'Model router off: every request uses the session model.' }
      case 'split': {
        const split = rest[0] === 'off' ? 'off' : 'sequential'
        await save({ ...current, split })
        return {
          text:
            split === 'off'
              ? 'Multi-part prompts now run in one turn on the model their hardest part needs.'
              : 'Multi-part prompts now run part by part, each on its own model.',
        }
      }
      case 'explain': {
        const text = e.args.trim().slice('explain'.length).trim()
        if (!text) return { text: 'Usage: /router explain <a prompt to classify>' }
        const p = plan(text, { inherited: (await read($, lastTier)) ?? undefined })
        return { text: ['Dry run (rules only, nothing sent):', ...describePlan(p, config)].join('\n') }
      }
      case 'reset':
        await update($, stats, () => EMPTY_STATS)
        await $.store.set('lifetime', EMPTY_STATS)
        return { text: 'Router stats reset.' }
      case 'help':
        return {
          text: [
            '/router                 status and savings',
            '/router on | off        turn routing on or off',
            '/router split on | off  run multi-part prompts part by part, or whole',
            '/router explain <text>  show how a prompt would be routed',
            '/router reset           clear the savings counters',
            'Prompt prefixes: !haiku !sonnet !opus !fable force a model for one prompt; !nosplit keeps it whole.',
          ].join('\n'),
        }
      default: {
        const s = await read($, stats)
        const lifetime = ((await $.store.get('lifetime')) as RouterStats | undefined) ?? EMPTY_STATS
        const last = await read($, lastTier)
        return {
          text: [
            `Model router: ${current.isEnabled ? 'on' : 'off'}, multi-part prompts ${
              current.split === 'sequential' ? 'split' : 'kept whole'
            }, classifier ${config.classifier}`,
            `Tiers: fast → ${config.models.fast}, balanced → ${config.models.balanced}, deep → ${config.models.deep}, max (!max) → ${config.models.max}`,
            `Last tier: ${last ?? 'none yet'}`,
            'This session:',
            ...describeStats(s).map(l => `  ${l}`),
            'All sessions:',
            ...describeStats(lifetime).map(l => `  ${l}`),
            'Costs are estimates from first-party API prices; /router help for commands.',
          ].join('\n'),
        }
      }
    }
  })

  on('prompt.submit', async ($, e, next) => {
    const current = await read($, settings)
    if (!current.isEnabled) return next(e)

    // A part this plugin queued earlier: route it as planned
    if (e.origin.kind === 'plugin' && e.origin.name === NAME) {
      const [head, ...rest] = await read($, queue)
      if (head) {
        await update($, queue, () => rest)
        await update($, pending, () => routeOf(head, head.index, head.total))
      }
      return next(e)
    }

    const isPerson = e.origin.kind === 'composer' || e.origin.kind === 'bridge' || e.origin.kind === 'sdk'
    if (!isPerson || e.text.trimStart().startsWith('/')) return next(e)

    // A new prompt from the person replaces any parts still waiting
    const waiting = (await read($, queue)).length
    if (waiting > 0) {
      await update($, queue, () => [])
      $.ui.toast(`Router: dropped ${waiting} queued part${waiting === 1 ? '' : 's'} for your new prompt`)
    }

    let p = plan(e.text, { inherited: (await read($, lastTier)) ?? undefined })
    if (config.classifier === 'hybrid' && !p.forced) p = await refine($, p, config.models.fast)
    const text = p.text.trim() ? p.text : e.text

    // Typed into a running turn: raise that turn's tier if this asks for more
    if (e.turnId) {
      const turnId = e.turnId
      await update($, turns, all => {
        const route = all[turnId]
        if (!route || rank(route.tier) >= rank(p.tier)) return all
        return { ...all, [turnId]: { ...route, tier: p.tier, escalated: 'a message typed mid-turn asked for more' } }
      })
      return next({ ...e, text })
    }

    await addStats($, s => ({ ...s, prompts: s.prompts + 1 }))
    const [first, ...rest] = p.parts
    const shouldSplit = current.split === 'sequential' && !p.noSplit && first !== undefined && rest.length > 0

    if (!shouldSplit || !first) {
      const lead = first ?? p.parts[0]
      await update($, pending, () => ({
        tier: p.tier,
        category: lead?.category ?? 'context',
        reasons: lead?.reasons ?? [],
      }))
      const result = await next({ ...e, text })
      if (result.drop !== undefined) await update($, pending, () => null)
      return result
    }

    const total = p.parts.length
    await update($, queue, () =>
      rest.map((part, i) => ({
        text: part.text,
        tier: part.tier,
        category: part.category,
        reasons: part.reasons,
        index: i + 2,
        total,
      })),
    )
    await update($, pending, () => routeOf(first, 1, total))
    await addStats($, s => ({ ...s, splits: s.splits + 1 }))
    $.ui.toast(
      `Router split this prompt: ${p.parts
        .map((part, i) => `${i + 1}) ${label(config.models[part.tier])} · ${part.category}`)
        .join('  ')}`,
    )

    const instruction = [
      `[model-router] The user's message has ${total} parts, and each runs as its own turn on the model it needs.`,
      `In this turn handle ONLY part 1: "${first.text}"`,
      'Do not start the later parts; they arrive as follow-up messages right after this turn:',
      ...rest.map((part, i) => `- part ${i + 2}: "${clip(part.text, 300)}"`),
    ].join('\n')
    const result = await next({ ...e, text, context: [...(e.context ?? []), instruction] })
    if (result.drop !== undefined) {
      await update($, pending, () => null)
      await update($, queue, () => [])
    }
    return result
  }).catch(($, e, next) => next(e)) // never hold a prompt back over a router fault

  on('turn.start', async ($, e, next) => {
    const route = await read($, pending)
    if (route) {
      await update($, pending, () => null)
      await update($, turns, all => {
        // keep the map small: a turn's entry is removed at its end anyway
        const kept = Object.entries(all).slice(-20)
        return { ...Object.fromEntries(kept), [e.turnId]: route }
      })
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId) return yield* next(e)
    const current = await read($, settings)
    const route = (await read($, turns))[e.turnId]
    if (!current.isEnabled || !route) return yield* next(e)

    const target = config.models[route.tier]
    const before = await read($, cache)
    const choice = config.cacheAware
      ? chooseSwitch({
          current: before.model,
          target,
          contextTokens: before.contextTokens,
          expectedOutput: EXPECTED_OUTPUT[route.tier],
          lastAt: before.at,
          now: await $.clock.now(),
        })
      : { model: target }

    const part = route.part ? ` · part ${route.part.index}/${route.part.total}` : ''
    const kept = choice.keptBecause ? ' (cache kept)' : ''
    $.ui.status(`⇄ ${label(choice.model)} · ${route.category}${part}${kept}`)

    const step = config.setEffort ? { ...e, model: choice.model, effort: EFFORT[route.tier] } : { ...e, model: choice.model }
    const result = yield* next(step)

    if (result.usage) {
      const usage = result.usage
      const answered = usage.model || choice.model
      const cost = costOf(answered, usage)
      const baseline = costOf(e.model, usage)
      await addStats($, s => {
        const tally = s.byModel[answered] ?? { steps: 0, cost: 0 }
        return {
          ...s,
          steps: s.steps + 1,
          cost: s.cost + cost,
          baseline: s.baseline + baseline,
          byModel: { ...s.byModel, [answered]: { steps: tally.steps + 1, cost: tally.cost + cost } },
        }
      })
      const at = await $.clock.now()
      await update($, cache, () => ({
        model: choice.model,
        at,
        contextTokens: promptTokens(usage) + usage.output_tokens,
      }))
    }

    if (config.escalate) {
      const why = escalation(route, e.index, result)
      if (why) {
        const tier = nextTier(route.tier)
        await update($, turns, all => {
          const r = all[e.turnId]
          return r ? { ...all, [e.turnId]: { ...r, tier, escalated: why } } : all
        })
        $.ui.toast(`Router: ${label(choice.model)} ${why}, moving this turn to ${label(config.models[tier])}`)
      }
    }
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId) return result

    const route = (await read($, turns))[e.turnId]
    if (route) {
      await update($, lastTier, () => route.tier)
      await update($, turns, all => {
        const { [e.turnId]: _, ...rest } = all
        return rest
      })
    }

    const waiting = await read($, queue)
    const head = waiting[0]
    if (head && e.reason !== 'answer') {
      await update($, queue, () => [])
      $.ui.toast(`Router: the turn stopped, so ${waiting.length} remaining part${waiting.length === 1 ? ' was' : 's were'} not run`)
    } else if (head) {
      // after this turn has ended, so the part runs as a turn of its own
      $.clock.after(0, () => {
        void $.prompt
          .submit({
            text: `Continue with part ${head.index} of ${head.total} of the user's last message (the model router gave it its own turn): "${head.text}"`,
          })
          .catch(() => update($, queue, () => []))
      })
    } else {
      const s = await read($, stats)
      const saved = s.baseline - s.cost
      $.ui.status(saved > 0 ? `⇄ router · saved ≈ ${formatUsd(saved)} this session` : '⇄ router on')
    }
    return result
  })
}

