// Prompt classification and segmentation: pure functions, no `$`, so the
// tests and the `/router explain` command can run them directly.

import type { Category, Tier } from '../types'

export type { Category, Tier }

export const TIERS: readonly Tier[] = ['fast', 'balanced', 'deep', 'max']

export type PartPlan = {
  text: string
  category: Category
  tier: Tier
  score: number
  // 0..1: how far the score sits from the nearest tier boundary
  confidence: number
  reasons: string[]
}

export type Plan = {
  parts: PartPlan[]
  // the highest tier over all parts
  tier: Tier
  forced?: Tier
  noSplit: boolean
  // the prompt with any `!opus`-style override stripped
  text: string
}

const BASE: Record<Category, number> = {
  chat: 0,
  question: 1,
  lookup: 1.5,
  edit: 2.5,
  debug: 3.5,
  review: 4,
  build: 4.5,
  design: 6.5,
  'follow-up': 0,
  context: 0,
}

// fast < 2 <= balanced < 5.5 <= deep; `max` is reached only by override
const FAST_BELOW = 2
const DEEP_FROM = 5.5

const OVERRIDES: Record<string, Tier> = {
  haiku: 'fast',
  fast: 'fast',
  cheap: 'fast',
  sonnet: 'balanced',
  balanced: 'balanced',
  opus: 'deep',
  deep: 'deep',
  fable: 'max',
  max: 'max',
}

const REQUEST_PREFIX =
  /^(?:(?:can|could|would|will) you(?: please)?|please|pls|i (?:want|need|would like|'d like)(?: you)? to|help me(?: to)?|let'?s|go ahead and|try to)\s+/i

const RE = {
  chat: /^(?:hi|hello|hey|yo|thanks|thank you|thx|cool|nice|great|awesome|good (?:morning|night)|bye)\b/i,
  followUp:
    /^(?:yes|yep|yeah|yup|ok(?:ay)?|sure|go ahead|do it|continue|proceed|sounds good|lgtm|ship it|keep going|go on|go for it|approved?|that works|perfect|same (?:for|with)|now do|do the same|again|retry|try again)\b/i,
  design:
    /\b(?:architect\w*|system design|design (?:a|an|the) (?:system|architecture|schema|api|database)|trade-?offs?|migrat\w+|scalab\w+|from scratch|end-to-end|rewrite (?:the|it|everything)|overhaul|re-?architect\w*|plan (?:out|the) (?:architecture|system|migration))\b/i,
  buildVerb:
    /\b(?:build|implement|develop|scaffold|create|make|write|generate|set ?up|integrate|port|convert)\b/i,
  buildObject:
    /\b(?:app|application|feature|component|page|screen|api|endpoint|service|server|backend|frontend|function|class|module|script|mod|plugin|extension|website|site|landing|dashboard|tool|game|cli|bot|database|schema|test(?:s| suite)?|pipeline|workflow|integration|system|library|sdk|form|ui|crud)\b/i,
  strongBuild: /\b(?:build|implement|develop|scaffold)\b/i,
  edit: /\b(?:rename|change|update|tweak|adjust|replace|remove|delete|move|bump|fix (?:the |a )?typo|reformat|format|reword|translate|add (?:a |an |the )?(?:comment|log|line|field|button|link|import|prop|option|flag|column|test))\b/i,
  debug:
    /\bwhy (?:won'?t|can'?t|isn'?t|doesn'?t|don'?t|didn'?t|aren'?t|is (?:\w+ ){0,4}not|does (?:\w+ ){0,4}not)\b|\bwhy (?:does|is|do|are|did)\b.*\b(?:wrong|fail\w*|reject\w*|slow|hang\w*|break\w*|empty|null|undefined|crash\w*)\b|\b(?:bug|error|exception|crash\w*|fail\w*|broken|doesn'?t work|does not work|not working|stack ?trace|traceback|undefined is not|null pointer|segfault|regression|debug\w*|fix(?:es|ed|ing)?)\b/i,
  review:
    /\b(?:review|audit|analy[sz]e|optimi[sz]e|refactor\w*|security|performance|improve the|clean ?up)\b/i,
  lookup:
    /\b(?:find|search|where (?:is|are|do|does)|locate|list|show me|grep|which files?|summari[sz]e|read (?:the|this)|look up|check (?:if|whether|what))\b/i,
  question:
    /^(?:what|why|how|when|where|who|whom|which|is|are|am|was|were|can|could|should|does|do|did|will|would|has|have)\b|\?\s*$|\b(?:explain|difference between|meaning of|tell me|what'?s the|is there a|eli5)\b/i,
  scope:
    /\b(?:entire|whole|all (?:the )?files|across (?:the|all)|codebase|multiple|several|every|full(?:-stack| stack)?|complete|production(?:-ready)?|robust|scalable|end-to-end|from scratch|architecture|complex|comprehensive|thorough)\b/gi,
  hard: /\b(?:concurren\w*|race condition|memory leak|deadlock|distributed|security|auth\w*|encrypt\w*|performance|algorithm\w*|optimi[sz]\w*|migration|state machine|real-?time|async\w*|multi-?thread\w*|caching|cache invalidation|consensus|compiler|parser)\b/gi,
  simple:
    /\b(?:simple|quick(?:ly)?|small|tiny|just|only|minor|brief(?:ly)?|short|one-?line(?:r)?|typo|trivial|basic)\b/gi,
  file: /\b[\w./-]+\.(?:tsx?|jsx?|mjs|cjs|py|go|rs|rb|java|kt|swift|c|cc|cpp|h|hpp|cs|php|css|scss|html|md|json|ya?ml|toml|sql|sh)\b/gi,
  codeFence: /```/,
  stackTrace: /(?:^\s+at .+\(.+:\d+(?::\d+)?\)|Traceback \(most recent call last\)|^\w*(?:Error|Exception):)/m,
  listItem: /^\s*(?:\d+[.)]|[-*•])\s+/,
}

function count(re: RegExp, text: string): number {
  return (text.match(re) ?? []).length
}

function words(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length
}

export function tierOf(score: number): Tier {
  if (score < FAST_BELOW) return 'fast'
  if (score < DEEP_FROM) return 'balanced'
  return 'deep'
}

export function maxTier(a: Tier, b: Tier): Tier {
  return TIERS.indexOf(a) >= TIERS.indexOf(b) ? a : b
}

export function rank(tier: Tier): number {
  return TIERS.indexOf(tier)
}

function categorize(raw: string): { category: Category; reason: string } {
  const text = raw.trim()
  const n = words(text)
  const isRequest = REQUEST_PREFIX.test(text)
  const body = text.replace(REQUEST_PREFIX, '')

  if (n <= 12 && RE.followUp.test(text)) {
    return { category: 'follow-up', reason: 'short follow-up: inherits the last tier' }
  }
  if (n <= 6 && RE.chat.test(text) && !RE.buildVerb.test(text)) {
    return { category: 'chat', reason: 'small talk' }
  }
  if (RE.design.test(body)) {
    return { category: 'design', reason: 'architecture / design / migration' }
  }
  const asksHow = !isRequest && /^(?:how|what|why|which|should)\b/i.test(body)
  if (!asksHow && RE.buildVerb.test(body) && (RE.buildObject.test(body) || RE.strongBuild.test(body))) {
    return { category: 'build', reason: 'build / implement request' }
  }
  if (/\bfix (?:the |a |this |that )?typos?\b/i.test(body)) {
    return { category: 'edit', reason: 'small edit' }
  }
  if (RE.debug.test(body) || RE.stackTrace.test(raw)) {
    return { category: 'debug', reason: 'debugging' }
  }
  if (!asksHow && RE.review.test(body)) {
    return { category: 'review', reason: 'review / refactor / optimise' }
  }
  if (!asksHow && RE.edit.test(body)) {
    return { category: 'edit', reason: 'small edit' }
  }
  if (RE.lookup.test(body)) {
    return { category: 'lookup', reason: 'lookup / read-only' }
  }
  if (RE.question.test(text) || asksHow) {
    return { category: 'question', reason: 'question' }
  }
  if (isRequest || RE.buildVerb.test(body)) {
    return { category: 'edit', reason: 'generic request' }
  }
  return { category: 'context', reason: 'no task of its own' }
}

export function classifyPart(text: string, inherited?: Tier): PartPlan {
  const { category, reason } = categorize(text)
  const reasons = [reason]
  let score = BASE[category]

  const n = words(text)
  if (n > 300) {
    score += 2
    reasons.push('very long prompt')
  } else if (n > 120) {
    score += 1.5
    reasons.push('long prompt')
  } else if (n > 40) {
    score += 1
    reasons.push('detailed prompt')
  }

  const scope = Math.min(2, count(RE.scope, text))
  if (scope > 0) {
    score += scope * 1.5
    reasons.push('large scope')
  }
  const isAsking = category === 'question' || category === 'lookup' || category === 'chat'
  // a hard topic makes work harder, not a question about it
  const hard = isAsking ? 0 : Math.min(2, count(RE.hard, text))
  if (hard > 0) {
    score += hard
    reasons.push('hard domain')
  }
  const simple = Math.min(2, count(RE.simple, text))
  if (simple > 0) {
    score -= simple
    reasons.push('marked simple')
  }
  if (RE.codeFence.test(text)) {
    score += 0.5
    reasons.push('includes code')
  }
  if (RE.stackTrace.test(text)) {
    score += 0.5
    reasons.push('includes a stack trace')
  }
  const files = new Set((text.match(RE.file) ?? []).map(f => f.toLowerCase())).size
  if (files >= 3) {
    score += 1
    reasons.push(`${files} files named`)
  }
  const steps = text.split('\n').filter(line => RE.listItem.test(line)).length
  if (steps >= 3) {
    score += 1
    reasons.push(`${steps} listed steps`)
  }

  // The question-like categories never escalate past balanced on wording alone
  if (isAsking) {
    score = Math.min(score, DEEP_FROM - 0.5)
  }
  score = Math.max(0, Math.round(score * 10) / 10)

  if (category === 'follow-up' && inherited) {
    return { text, category, tier: inherited, score, confidence: 1, reasons }
  }

  const distance = Math.min(Math.abs(score - FAST_BELOW), Math.abs(score - DEEP_FROM))
  const confidence = Math.min(1, distance / 1.5)
  const isDefaulted = category === 'context' || reason === 'generic request'

  return {
    text,
    category,
    tier: tierOf(score),
    score,
    confidence: isDefaulted ? Math.min(confidence, 0.3) : confidence,
    reasons,
  }
}

const CONNECTOR =
  /(?:[,;]\s*(?:and\s+)?|\s+and\s+)(?=(?:then|after that|afterwards|once (?:that'?s|it'?s|you'?re) done|finally)\b)/i

// Splits a prompt into the pieces a person would number: list items,
// paragraphs, sentences, and "..., then ..." clauses. Code fences stay whole.
export function segment(text: string): string[] {
  const fences: string[] = []
  const masked = text.replace(/```[\s\S]*?(?:```|$)/g, block => {
    fences.push(block)
    return `\u0000${fences.length - 1}\u0000`
  })
  const restore = (s: string) => s.replace(/\u0000(\d+)\u0000/g, (_, i) => fences[Number(i)] ?? '')

  const blocks: string[] = []
  let paragraph: string[] = []
  const flush = () => {
    if (paragraph.length > 0) blocks.push(paragraph.join(' '))
    paragraph = []
  }
  for (const line of masked.split('\n')) {
    if (line.trim() === '') {
      flush()
    } else if (RE.listItem.test(line)) {
      flush()
      blocks.push(line.replace(RE.listItem, ''))
    } else {
      paragraph.push(line.trim())
    }
  }
  flush()

  const pieces: string[] = []
  for (const block of blocks) {
    for (const sentence of block.split(/(?<=[.?!])\s+(?=[A-Z\u0000])/)) {
      for (const clause of sentence.split(CONNECTOR)) {
        const cleaned = clause
          .replace(/^(?:and\s+)?(?:then|after that|afterwards|finally)\b[,:]?\s*/i, '')
          .trim()
        if (cleaned) pieces.push(restore(cleaned))
      }
    }
  }
  return pieces
}

function parseOverride(text: string): { text: string; forced?: Tier; noSplit: boolean } {
  let rest = text
  let forced: Tier | undefined
  let noSplit = false
  for (;;) {
    const m = rest.match(/^\s*!([a-z]+)\b\s*/i)
    if (!m) break
    const word = (m[1] ?? '').toLowerCase()
    if (word === 'nosplit' || word === 'whole') {
      noSplit = true
    } else if (OVERRIDES[word]) {
      forced = OVERRIDES[word]
    } else {
      break
    }
    rest = rest.slice(m[0].length)
  }
  return { text: rest, forced, noSplit }
}

export type PlanOptions = {
  inherited?: Tier
  maxParts?: number
}

export function plan(input: string, options: PlanOptions = {}): Plan {
  const { text, forced, noSplit } = parseOverride(input)
  const maxParts = options.maxParts ?? 4

  if (forced) {
    const part: PartPlan = {
      text,
      category: 'context',
      tier: forced,
      score: 0,
      confidence: 1,
      reasons: [`forced with !${forced}`],
    }
    return { parts: [part], tier: forced, forced, noSplit: true, text }
  }

  const pieces = segment(text).map(piece => classifyPart(piece, options.inherited))

  // Context sentences ("I have a React app.") join the piece after them; a
  // trailing one joins the piece before it.
  const attached: PartPlan[] = []
  let carry: string[] = []
  for (const piece of pieces) {
    if (piece.category === 'context') {
      carry.push(piece.text)
      continue
    }
    attached.push(carry.length > 0 ? { ...piece, text: [...carry, piece.text].join(' ') } : piece)
    carry = []
  }
  const last = attached[attached.length - 1]
  if (carry.length > 0 && last) {
    attached[attached.length - 1] = { ...last, text: [last.text, ...carry].join(' ') }
  }

  // Neighbouring pieces of one kind (asking, or doing) are one task: a build
  // described over five sentences is one part, scored as a whole.
  const groups: PartPlan[][] = []
  for (const piece of attached) {
    const group = groups[groups.length - 1]
    const head = group?.[0]
    if (group && head && kindOf(head) === kindOf(piece)) group.push(piece)
    else groups.push([piece])
  }
  const parts = groups.map(group => {
    if (group.length === 1 && group[0]) return group[0]
    const whole = classifyPart(group.map(p => p.text).join('\n'), options.inherited)
    const top = group.reduce((a, b) => (rank(b.tier) > rank(a.tier) ? b : a))
    const tier = maxTier(whole.tier, top.tier)
    return { ...whole, tier, category: rank(top.tier) >= rank(whole.tier) ? top.category : whole.category }
  })

  const top = parts.reduce<Tier>((t, p) => maxTier(t, p.tier), 'fast')
  const isWorthSplitting =
    parts.length > 1 && parts.length <= maxParts && parts.some(p => rank(p.tier) < rank(top))
  if (noSplit || !isWorthSplitting) {
    const whole = classifyPart(text, options.inherited)
    const tier = maxTier(whole.tier, top)
    const category = parts.find(p => p.tier === tier)?.category ?? whole.category
    return { parts: [{ ...whole, tier, category }], tier, noSplit: true, text }
  }
  return { parts, tier: top, noSplit: false, text }
}

const ASKING: readonly Category[] = ['chat', 'question', 'lookup']

function kindOf(part: PartPlan): 'asking' | 'doing' {
  return ASKING.includes(part.category) ? 'asking' : 'doing'
}

