// What a request costs on each model family, and whether switching away from
// a model whose prompt cache is warm is worth it. Prices are USD per million
// tokens, Anthropic first-party rates for the 5.5 generation (cached
// 2026-10-06); Bedrock and Vertex bill differently, so treat them as relative.

import type { ModelUsage } from 'claude-code'

export type Price = { input: number; output: number; cacheRead: number; cacheWrite: number }

const HAIKU: Price = { input: 0.1, output: 0.5, cacheRead: 0.01, cacheWrite: 0.125 }
// Haiku 5.5 bills prompts past 100K tokens at the higher rate
const HAIKU_LONG: Price = { input: 0.5, output: 2.5, cacheRead: 0.05, cacheWrite: 0.625 }
const SONNET: Price = { input: 2, output: 10, cacheRead: 0.2, cacheWrite: 2.5 }
const OPUS: Price = { input: 4, output: 20, cacheRead: 0.2, cacheWrite: 5 }
const FABLE: Price = { input: 10, output: 50, cacheRead: 0.25, cacheWrite: 12.5 }

// A prompt cache entry lives five minutes; leave a margin
export const CACHE_WARM_MS = 4.5 * 60 * 1000

export function family(model: string): 'haiku' | 'sonnet' | 'opus' | 'fable' {
  const m = model.toLowerCase()
  if (m.includes('haiku')) return 'haiku'
  if (m.includes('sonnet')) return 'sonnet'
  if (m.includes('fable') || m.includes('mythos')) return 'fable'
  return 'opus'
}

export function priceOf(model: string, promptTokens = 0): Price {
  switch (family(model)) {
    case 'haiku':
      return promptTokens > 100_000 ? HAIKU_LONG : HAIKU
    case 'sonnet':
      return SONNET
    case 'fable':
      return FABLE
    default:
      return OPUS
  }
}

export function promptTokens(usage: ModelUsage): number {
  return usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens
}

export function costOf(model: string, usage: ModelUsage): number {
  const p = priceOf(model, promptTokens(usage))
  return (
    (usage.input_tokens * p.input +
      usage.output_tokens * p.output +
      usage.cache_read_input_tokens * p.cacheRead +
      usage.cache_creation_input_tokens * p.cacheWrite) /
    1_000_000
  )
}

export type Switch = {
  // the model to send the request to
  model: string
  // why the target was not used, when it was not
  keptBecause?: string
}

// Decides between moving to `target` and staying on `current` for the next
// request. Moving up in capability always happens. Moving down is skipped when
// the conversation is long and `current` still holds it in cache, so that
// re-reading it uncached on the cheaper model would cost more than staying.
export function chooseSwitch(input: {
  current: string | undefined
  target: string
  contextTokens: number
  expectedOutput: number
  lastAt: number | undefined
  now: number
}): Switch {
  const { current, target, contextTokens, expectedOutput, lastAt, now } = input
  if (!current || current === target || lastAt === undefined) return { model: target }
  if (now - lastAt > CACHE_WARM_MS) return { model: target }

  const from = priceOf(current, contextTokens)
  const to = priceOf(target, contextTokens)
  if (to.output >= from.output) return { model: target }

  const stay = (contextTokens * from.cacheRead + expectedOutput * from.output) / 1_000_000
  const move = (contextTokens * to.cacheWrite + expectedOutput * to.output) / 1_000_000
  if (move < stay) return { model: target }
  return {
    model: current,
    keptBecause: `cache warm on ${current}: staying costs ~$${stay.toFixed(4)}, switching ~$${move.toFixed(4)}`,
  }
}

export function formatUsd(usd: number): string {
  if (usd >= 1) return `$${usd.toFixed(2)}`
  if (usd >= 0.01) return `$${usd.toFixed(3)}`
  return `$${usd.toFixed(4)}`
}

