// The model-router's type contract: the values it keeps in `$.state`.

export type Tier = 'fast' | 'balanced' | 'deep' | 'max'

export type Category =
  | 'chat'
  | 'question'
  | 'lookup'
  | 'edit'
  | 'debug'
  | 'review'
  | 'build'
  | 'design'
  | 'follow-up'
  | 'context'

export type SplitMode = 'sequential' | 'off'

export type RouterSettings = { isEnabled: boolean; split: SplitMode }

// How one turn is routed; its tier may rise while the turn runs.
export type TurnRoute = {
  tier: Tier
  category: Category
  reasons: string[]
  part?: { index: number; total: number }
  escalated?: string
}

// A part of a split prompt still waiting for its own turn.
export type QueuedPart = {
  text: string
  tier: Tier
  category: Category
  reasons: string[]
  index: number
  total: number
}

// The model the last main-loop request went to, and how large the prompt was:
// what the cache-aware switch decision reads.
export type CacheState = { model?: string; at?: number; contextTokens: number }

export type ModelTally = { steps: number; cost: number }

export type RouterStats = {
  prompts: number
  splits: number
  steps: number
  cost: number
  // what the same requests would have cost on the session's own model
  baseline: number
  byModel: Record<string, ModelTally>
}

// `Tier` inside the block below would name the engine's own plugin tier
export type RouteTier = Tier

declare module 'claude-code' {
  interface PluginState {
    'model-router': {
      settings: RouterSettings
      turns: Record<string, TurnRoute>
      pending: TurnRoute | null
      queue: QueuedPart[]
      cache: CacheState
      lastTier: RouteTier | null
      stats: RouterStats
    }
  }
}
